schema:
CREATE TABLE EMPLOYEE (
    EMPLOYEE_ID INT,
    NAME VARCHAR(255),
    EXPERIENCE_YEARS INT,
    PRIMARY KEY (EMPLOYEE_ID),
    CHECK (EXPERIENCE_YEARS >= 0)
);
CREATE TABLE PROJECT (
    PROJECT_ID INT,
    EMPLOYEE_ID INT,
    PRIMARY KEY (PROJECT_ID, EMPLOYEE_ID),
    FOREIGN KEY (EMPLOYEE_ID) REFERENCES EMPLOYEE(EMPLOYEE_ID)
);

counterexample:
-- No INSERT statements needed as queries are equivalent
-- Example data that produces same results for both queries:
INSERT INTO EMPLOYEE (EMPLOYEE_ID, NAME, EXPERIENCE_YEARS) VALUES (1, 'Alice', 5);
INSERT INTO EMPLOYEE (EMPLOYEE_ID, NAME, EXPERIENCE_YEARS) VALUES (2, 'Bob', 3);
INSERT INTO PROJECT (PROJECT_ID, EMPLOYEE_ID) VALUES (100, 1);
INSERT INTO PROJECT (PROJECT_ID, EMPLOYEE_ID) VALUES (100, 2);
INSERT INTO PROJECT (PROJECT_ID, EMPLOYEE_ID) VALUES (200, 1);

